import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.XeSgnAkN.js";const u=JSON.parse('{"title":"Connect an AI agent","description":"","frontmatter":{},"headers":[],"relativePath":"agents.md","filePath":"agents.md","lastUpdated":1791226614000}'),s={name:"agents.md"};function r(d,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="connect-an-ai-agent" tabindex="-1">Connect an AI agent <a class="header-anchor" href="#connect-an-ai-agent" aria-label="Permalink to &quot;Connect an AI agent&quot;">​</a></h1><p>Pigeon Cloud lets the AI assistants you already use work from the same inbox as you. Agents connect through <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a>, so there is nothing to install, and they use your own Claude or ChatGPT subscription.</p><p>Pigeon Cloud is optional. Without it, Pigeon only writes to your local folder.</p><h2 id="server-address" tabindex="-1">Server address <a class="header-anchor" href="#server-address" aria-label="Permalink to &quot;Server address&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://api.usepigeon.cc/mcp</span></span></code></pre></div><p>When you add it, a Pigeon page opens. Sign in with Apple or an email code, then allow the app. You can see and disconnect every connected app in <strong>Settings → Pigeon Cloud → Connected apps</strong>.</p><h2 id="claude" tabindex="-1">Claude <a class="header-anchor" href="#claude" aria-label="Permalink to &quot;Claude&quot;">​</a></h2><ol><li>On claude.ai, open <strong>Customize → Connectors</strong> and add a custom connector.</li><li>Paste the server address and click <strong>Add</strong>. Leave the advanced OAuth fields empty.</li><li>In a chat, turn the connector on from the <strong>+</strong> menu under <strong>Connectors</strong>.</li></ol><p>Connectors you add on claude.ai also work in Claude Desktop and the mobile apps. On Team and Enterprise plans, an owner adds the connector under <strong>Organization settings → Connectors</strong> first.</p><h2 id="chatgpt-and-other-mcp-clients" tabindex="-1">ChatGPT and other MCP clients <a class="header-anchor" href="#chatgpt-and-other-mcp-clients" aria-label="Permalink to &quot;ChatGPT and other MCP clients&quot;">​</a></h2><p>Any client that supports remote MCP servers with OAuth can connect with the same address. In ChatGPT this needs <strong>Developer mode</strong>, which is not available on every plan. Turn it on in settings, then create an app for a remote MCP server with the address above.</p><h2 id="how-agents-and-you-share-work" tabindex="-1">How agents and you share work <a class="header-anchor" href="#how-agents-and-you-share-work" aria-label="Permalink to &quot;How agents and you share work&quot;">​</a></h2><p>Tasks are ordinary Pigeon lines, with a few extra keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>for:agent</code></td><td>Work for an agent. <code>for:me</code> is work handed back to you.</td></tr><tr><td><code>by:</code></td><td>Who wrote the task. Pigeon sets it from the connected app&#39;s name.</td></tr><tr><td><code>from:</code></td><td>The task this one follows up on.</td></tr><tr><td><code>ref:</code></td><td>A note with the agent&#39;s longer output, e.g. <code>_notes/k3f9x2ab.md</code>.</td></tr></tbody></table><p>A typical loop:</p><ol><li>You capture <code>Draft the launch post for:agent @Marketing</code>.</li><li>You ask your assistant to check its Pigeon tasks. It writes the draft to a note and completes the task.</li><li>It adds <code>Review launch post for:me</code> with a <code>ref:</code> to the note, so the next step shows up in your inbox.</li></ol><p>Agents are told not to publish, send, pay or delete on your behalf unless the task explicitly asks them to. They hand those steps back to you instead.</p>',17)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
